-- ============================================================
-- 0041 — Curadoria dos textos-base da RNC: Civil (CV, exceto CV-02 já curado na 0038)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- CV-01 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o erro de greide ou de off-set comprometer a cota de assentamento de estruturas, drenagem ou pavimento subsequente, ou quando a divergência já tiver orientado a execução de camadas cobertas.',
  texto_fundamentacao_normativa = 'A locação da terraplenagem (greides, platôs, bermas e off-sets) deve reproduzir fielmente o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, sendo esta a referência geométrica que condiciona cotas de corte/aterro, declividades e a interface com as etapas seguintes. O critério "Greides, platôs e off-sets conforme projeto na revisão vigente" integra o plano de inspeção da obra e constitui requisito verificável de aceitação: a conferência é feita por levantamento topográfico amarrado à rede de referência (RN e poligonal) da obra. A adoção de revisão superada ou de marcos não conferidos descaracteriza o controle geométrico da etapa, independentemente da qualidade construtiva do serviço.',
  texto_risco_consequencia = 'Executar a terraplenagem a partir de topografia de referência incorreta ou desatualizada propaga o erro geométrico para todas as camadas e estruturas apoiadas, resultando em cotas fora de projeto, declividades de drenagem invertidas e desencontro com fundações e pavimento, o que tende a exigir retrabalho, refazimento de camadas e revisão de projeto, com sobrecusto e atraso. Enquanto a referência não for corrigida e revalidada, todo serviço locado sobre ela permanece sob desvio. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) revalidar os marcos e a poligonal de apoio a partir das RN oficiais da obra e confirmar que a base topográfica corresponde à revisão vigente do projeto executivo aprovado; (ii) reimplantar greides, platôs e off-sets conferindo cotas e alinhamentos, e levantar a extensão do serviço eventualmente executado sobre a referência incorreta, definindo o retrabalho necessário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo levantamento topográfico assinado pelo responsável técnico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o material provier de jazida não autorizada, não possuir caracterização/CBR válido ou apresentar resultado abaixo do mínimo especificado, sobretudo em aterros de suporte de pavimento ou de estruturas.',
  texto_fundamentacao_normativa = 'O solo destinado ao aterro deve atender aos parâmetros da especificação técnica quanto à granulometria, aos limites de consistência e à capacidade de suporte, comprovados por ensaios de caracterização e de Índice de Suporte Califórnia (CBR), conforme a NBR 9895 (Solo — Índice de suporte Califórnia — ISC), além da procedência de jazida licenciada/autorizada. O critério "Caracterização/CBR conforme especificação; jazida autorizada" e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, definem o material apto e vedam o emprego de solos expansivos, orgânicos ou contaminados. A liberação do material é requisito prévio e verificável ao lançamento em obra.',
  texto_risco_consequencia = 'Empregar material de aterro sem caracterização válida, com CBR inferior ao especificado ou de jazida não autorizada compromete a capacidade de suporte e a estabilidade do maciço, favorecendo recalques diferenciais, empolamento/expansão e ruptura, com risco de patologias nas estruturas e pavimentos apoiados e passivo ambiental/legal pela origem irregular do solo. Enquanto material não conforme permanecer incorporado, o desvio de qualidade do maciço fica ativo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o lançamento do material questionado e obter/atualizar a caracterização completa e o ensaio de CBR da jazida, confrontando os resultados com a especificação e confirmando a autorização/licenciamento da fonte; (ii) segregar e remover o material não conforme já lançado ou substituí-lo por solo aprovado, quando a análise técnica indicar; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), laudos de ensaio e comprovante de origem da jazida, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando camadas com espessura solta acima do especificado ou com número de passadas insuficiente já tiverem sido cobertas, impedindo a inspeção e o retrabalho localizado sem demolição.',
  texto_fundamentacao_normativa = 'A compactação deve ser executada em camadas de espessura solta compatível com a energia do equipamento, respeitando o número de passadas definido para o rolo empregado, condição que assegura a densificação uniforme em toda a altura da camada. O controle tecnológico da execução de aterros é tratado pela NBR 5681, e o critério "Espessura solta ≤ especificada; nº de passadas do equipamento definido", em conjunto com a especificação de serviço e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, fixa os parâmetros de lançamento e de energia de compactação. Camadas espessas demais ou insuficientemente compactadas não atingem densificação homogênea, ainda que ensaios pontuais de superfície pareçam satisfatórios.',
  texto_risco_consequencia = 'Lançar camadas com espessura solta superior à especificada ou aplicar número de passadas inferior ao definido gera compactação heterogênea, com o interior da camada menos densificado que a superfície, resultando em zonas de baixa capacidade de suporte, recalques diferenciais e perda de estabilidade do maciço ao longo do tempo. Como o defeito fica encoberto pelas camadas seguintes, a condição permanece latente até manifestar-se como patologia. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reescarificar a camada não conforme e relançá-la com espessura solta dentro do limite especificado, aplicando o número de passadas definido para o equipamento em uso; (ii) padronizar o procedimento (espessura de lançamento, plano de rolagem e equipamento) e registrar o controle de passadas por camada, evitando reincidência; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo controle da camada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — grau de compactação abaixo do mínimo de projeto compromete diretamente a capacidade de suporte do maciço; manter Maior somente em desvio pontual isolado, já corrigido e reensaiado com aprovação.',
  texto_fundamentacao_normativa = 'O grau de compactação (GC) da camada deve atingir o mínimo estabelecido em projeto — tipicamente GC ≥ 95% ou 98% da massa específica seca máxima do ensaio de Proctor —, com a frequência de ensaios prevista no plano de controle. Aplicam-se a NBR 5681 (controle tecnológico da execução de aterros) e a NBR 7182 (ensaio de compactação — Proctor), que definem o parâmetro de referência e o método, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "GC ≥ 95/98% do Proctor conforme projeto; frequência de ensaios atendida" é requisito quantitativo e verificável de aceitação da camada, e sua comprovação é condição para a liberação da camada seguinte.',
  texto_risco_consequencia = 'Camada com grau de compactação inferior ao mínimo de projeto, ou sem a frequência de ensaios exigida, não tem sua capacidade de suporte comprovada, expondo o maciço a recalques, deformações e ruptura sob carga, com risco direto às fundações, ao pavimento e às estruturas apoiadas. A ausência de ensaios na frequência prevista deixa trechos sem evidência de conformidade, mantendo o risco não caracterizado e ativo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reescarificar, corrigir a umidade se necessário e recompactar a camada reprovada até atingir o GC de projeto; (ii) reensaiar o trecho corrigido e complementar os ensaios faltantes de modo a cumprir a frequência especificada, arquivando os laudos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os resultados de GC aprovados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de umidade for acentuado (solo muito além do ramo úmido ou seco) e a camada já tiver sido compactada e coberta, ou quando resultar em reprovação do grau de compactação.',
  texto_fundamentacao_normativa = 'A compactação deve ocorrer com o solo na faixa de umidade ótima, dentro da tolerância especificada (tipicamente ±2% em relação à umidade ótima do Proctor), pois é nessa condição que o solo atinge a máxima densificação para a energia aplicada. A umidade ótima é determinada pelo ensaio de compactação conforme a NBR 7182, e o critério "Desvio dentro da tolerância (±2% típico) no momento da compactação", combinado à especificação de serviço e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, estabelece a janela de umidade de aceitação. O controle deve ser feito no momento da rolagem, e não apenas no material de empréstimo.',
  texto_risco_consequencia = 'Compactar o solo fora da faixa de umidade ótima reduz a eficiência da energia aplicada: acima do teor ótimo há risco de borrachudo e perda de suporte com o tempo, e abaixo dele a densificação fica incompleta, em ambos os casos resultando em grau de compactação insuficiente, recalques e instabilidade do maciço. Se a camada é coberta antes da correção, o desvio de umidade permanece incorporado e não recuperável sem retrabalho. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) medir a umidade do solo no momento da compactação e corrigi-la por aeração/revolvimento (solo úmido) ou por adição controlada de água com homogeneização (solo seco) até a faixa especificada; (ii) recompactar a camada e reensaiar o grau de compactação, confirmando o atendimento após o ajuste de umidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os registros de umidade e GC, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em período chuvoso ou quando a ausência de drenagem provisória já estiver causando erosão de taludes, saturação de camadas compactadas ou alagamento de praças de trabalho.',
  texto_fundamentacao_normativa = 'Durante a terraplenagem deve haver sistema de drenagem provisória (canaletas, leiras, saídas d''água e bacias de contenção) que conduza as águas pluviais e de escoamento sem provocar erosão nem acúmulo nas praças de serviço. O critério "Águas direcionadas sem erosão nem alagamento de praças" decorre das boas práticas de execução de terraplenagem e do controle de umidade do maciço, complementando o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e eventual plano de drenagem provisória da obra. O direcionamento controlado das águas é requisito de preservação do serviço executado e de segurança das frentes de trabalho.',
  texto_risco_consequencia = 'A ausência ou insuficiência da drenagem provisória permite que as águas pluviais erodam taludes e camadas recém-executadas, saturem o solo compactado — degradando o grau de compactação já obtido — e alaguem as praças, paralisando frentes e comprometendo a trafegabilidade e a segurança. O dano tende a se agravar a cada evento de chuva enquanto o escoamento não for disciplinado, exigindo recomposição de material perdido por carreamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar/complementar a drenagem provisória com canaletas, leiras de proteção e saídas d''água dimensionadas para conduzir o escoamento a pontos seguros, evitando lançamento erosivo; (ii) recompor o material erodido e reavaliar as camadas que tenham sofrido saturação, recompactando as que apresentarem perda de suporte; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do sistema implantado e das áreas recuperadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — taludes com inclinação mais íngreme que a de projeto ou sem proteção/bermas representam risco de instabilidade e deslizamento; manter Maior apenas quando a divergência for de acabamento superficial sem afetar a estabilidade global.',
  texto_fundamentacao_normativa = 'Os taludes de corte e aterro devem ser executados com a inclinação, as bermas e a proteção superficial (revestimento vegetal ou outra medida antierosiva) definidas em projeto, parâmetros que asseguram a estabilidade geotécnica do maciço. O critério "Inclinação, bermas e proteção superficial executadas" e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, com o respectivo estudo geotécnico, fixam a geometria de talude compatível com o material e as condições do local; a conferência da inclinação e das bermas é feita por levantamento topográfico. A geometria de talude é requisito de segurança verificável e não pode ser alterada em campo sem análise técnica.',
  texto_risco_consequencia = 'Taludes executados mais íngremes que o projeto, sem as bermas previstas ou sem proteção superficial, ficam sujeitos a erosão progressiva e a instabilização, podendo evoluir para escorregamentos que atingem frentes de trabalho, vias e estruturas próximas, com risco à integridade de pessoas e necessidade de contenção emergencial. A condição tende a piorar com a exposição às chuvas enquanto a geometria e a proteção não forem regularizadas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente a inclinação e a implantação das bermas, retaludando o trecho para a geometria de projeto; (ii) executar a proteção superficial prevista (revestimento vegetal ou medida antierosiva equivalente) e, havendo indício de instabilidade, submeter o caso à análise geotécnica antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo levantamento topográfico do talude, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o material excedente for depositado em local não licenciado/autorizado ou sem controle de volumes, configurando passivo ambiental e risco de autuação, ou quando o depósito comprometer a estabilidade da área.',
  texto_fundamentacao_normativa = 'O material excedente da terraplenagem deve ser destinado a bota-fora em local licenciado ou autorizado, com regularização geométrica do depósito e controle documentado dos volumes transportados. O critério "Local licenciado/autorizado; controle de volumes" decorre das exigências legais de destinação de resíduos/solos de escavação e das boas práticas ambientais e de gestão da obra, complementando o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e o plano de gestão ambiental aplicável. A comprovação da autorização e o balanço de volumes são requisitos verificáveis de conformidade legal e de rastreabilidade do movimento de terra.',
  texto_risco_consequencia = 'Destinar o excedente a bota-fora não licenciado ou sem controle de volumes gera passivo ambiental e exposição a autuações, embargos e responsabilização, além de risco de instabilidade e erosão do próprio depósito quando não regularizado, com possível assoreamento de drenagens e afetação de terceiros. Enquanto a destinação irregular persistir, mantêm-se ativos o passivo legal e o risco físico do material depositado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confirmar e arquivar a licença/autorização do local de bota-fora e implantar o controle de volumes por meio de registro de cargas transportadas; (ii) regularizar geometricamente o depósito, conformando taludes e drenagem, e, no caso de destinação irregular já realizada, promover a adequação ou remoção conforme orientação ambiental; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), a documentação de licenciamento e o balanço de volumes, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência de registro de liberação por camada impede rastrear a conformidade do maciço e permite encobrir camadas não ensaiadas; manter Maior apenas quando a liberação existir e faltar somente formalização documental pontual.',
  texto_fundamentacao_normativa = 'Cada camada deve ser formalmente liberada, com registro do controle topográfico e dos ensaios (grau de compactação e umidade), antes do lançamento da camada seguinte, garantindo a rastreabilidade e a conformidade sequencial do maciço. O critério "Registro de liberação (topografia + ensaio) antes da camada seguinte" integra o plano de inspeção da obra e, alinhado à sistemática de controle tecnológico de aterros da NBR 5681 e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, torna a liberação documentada condição de aceitação para prosseguir. Sem o registro, a camada é considerada não liberada, ainda que executada.',
  texto_risco_consequencia = 'Prosseguir com a camada seguinte sem o registro de liberação da anterior faz com que eventuais não conformidades de compactação, umidade ou geometria fiquem definitivamente encobertas e sem rastreabilidade, inviabilizando a verificação posterior e transferindo o risco de recalque e ruptura para a fase de uso, quando a correção exige demolição. A falta de registro compromete a evidência de qualidade de todo o trecho e mantém a dúvida sobre a integridade do maciço. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar/retomar imediatamente a sistemática de liberação por camada, condicionando o lançamento da camada seguinte ao registro assinado de topografia e ensaios da anterior; (ii) para as camadas já cobertas sem registro, reconstituir a evidência disponível e, quando não for possível comprovar a conformidade, executar ensaios de verificação (por sondagem/prova) para atestar o maciço; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e os registros de liberação/ensaios, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-01' and item_numero = 9;

-- CV-03 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de eixo ou cota exceder a tolerância a ponto de comprometer o alinhamento das fileiras (strings) ou a interface com estruturas de tracker já contratadas',
  texto_fundamentacao_normativa = 'A locação das fundações (eixos, alinhamento das linhas e cotas de referência) deve reproduzir a implantação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, condição comprovada por levantamento topográfico com equipamento aferido. O critério "Eixos e cotas dentro das tolerâncias do projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, pois é a locação que garante o casamento entre a malha de fundações e a geometria da estrutura de suporte dos módulos. Fundamenta-se no projeto de implantação e nas boas práticas de topografia de obra (partida amarrada em marcos geodésicos e conferência de fechamento).',
  texto_risco_consequencia = 'Locação executada fora dos eixos e cotas de projeto propaga o erro para toda a malha de fundações, desalinhando fileiras, inviabilizando a montagem dos perfis e trackers nas posições previstas e podendo exigir reexecução de estacas já cravadas, com sobrecusto e atraso de cronograma. Enquanto não corrigida, a condição mantém o erro de posicionamento ativo em cadeia. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reamarrar a locação a partir dos marcos geodésicos de referência e reconferir topograficamente eixos, alinhamentos e cotas do trecho, confrontando com o projeto de implantação aprovado; (ii) reposicionar os piquetes/gabaritos fora de tolerância e bloquear a cravação nos pontos afetados até o aceite topográfico; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha topográfica de conferência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se do controle de capacidade de carga da fundação; manter Crítica sempre que houver elemento sem registro de nega/profundidade ou com valores fora do previsto, rebaixando a Maior apenas quando a falha for exclusivamente documental e a cravação comprovadamente atender ao projeto',
  texto_fundamentacao_normativa = 'A cravação de cada elemento deve ser controlada e registrada (nega, profundidade cravada e/ou torque, conforme o tipo de estaca/perfil), compondo o mapa de cravação que evidencia o atingimento do critério de parada e da capacidade de carga previstos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplica-se a NBR 6122 (Projeto e execução de fundações), que exige controle de execução e registro individual dos elementos cravados. O critério "Nega/profundidade/torque por elemento (mapa de cravação)" é requisito verificável de aceitação e base de rastreabilidade da fundação.',
  texto_risco_consequencia = 'A ausência ou inconsistência do controle de cravação impede comprovar que cada elemento atingiu o critério de parada e a capacidade de carga de projeto, admitindo em obra fundações potencialmente subdimensionadas, com risco de recalques diferenciais e comprometimento da estabilidade da estrutura de suporte dos módulos. Sem o registro, a não conformidade fica oculta e não rastreável. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a liberação dos elementos sem controle e recompor o mapa de cravação por elemento (nega, profundidade e/ou torque), identificando os pontos fora do critério de projeto; (ii) submeter os elementos duvidosos a recravação ou a verificação complementar de capacidade de carga, tratando os reprovados conforme parecer do projetista de fundações; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o mapa de cravação assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a prova de arrancamento comprova a resistência à tração dos perfis, solicitação típica dos suportes de UFV; manter Crítica quando o ensaio não for realizado na frequência exigida ou reprovar na carga de projeto',
  texto_fundamentacao_normativa = 'Os perfis metálicos de fundação da usina fotovoltaica são solicitados predominantemente por esforços de arrancamento (tração) decorrentes da ação do vento sobre os módulos; por isso o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} prescreve prova de arrancamento (pull-out) em frequência amostral e carga de ensaio definidas. A verificação da capacidade à tração de fundações por prova de carga é objeto da NBR 6122 (Projeto e execução de fundações). O critério "Frequência e carga de ensaio conforme projeto (perfis de UFV)" é requisito verificável de aceitação e valida a premissa geotécnica adotada em projeto.',
  texto_risco_consequencia = 'Deixar de executar a prova de arrancamento na frequência e na carga previstas impede confirmar que os perfis resistem à tração de projeto, admitindo o risco de arrancamento ou afrouxamento das fundações sob carregamento de vento, com possível colapso de trechos de estrutura e dos módulos. A lacuna de ensaio mantém não verificada a segurança da fundação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar/complementar as provas de arrancamento na frequência amostral definida em projeto, aplicando a carga de ensaio especificada e registrando carga versus deslocamento; (ii) tratar os perfis reprovados conforme parecer do projetista (reforço, substituição ou revisão do critério de cravação), estendendo a amostragem no entorno do ponto reprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de ensaio, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de verticalidade ou a torção do perfil exceder a tolerância do fabricante a ponto de impedir a fixação ou introduzir esforços parasitas na estrutura do tracker',
  texto_fundamentacao_normativa = 'A verticalidade (prumo) e a torção dos perfis cravados devem permanecer dentro das tolerâncias de montagem definidas pelo fabricante do tracker/estrutura e reproduzidas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Por se tratar de interface com componente proprietário, a referência de aceitação é a especificação do fabricante e o projeto, complementadas pelas boas práticas de controle geométrico em campo (medição de prumo e de orientação por instrumento aferido). O critério "Dentro das tolerâncias do fabricante do tracker/estrutura" é requisito verificável de aceitação da fundação para liberação da montagem.',
  texto_risco_consequencia = 'Perfis fora de prumo ou torcidos além da tolerância impedem o encaixe correto das peças do tracker, obrigam a improvisos de montagem e introduzem esforços não previstos (excentricidades e flexões) na estrutura e nas fixações, reduzindo a vida útil do conjunto e podendo inviabilizar a operação do rastreador. Enquanto não corrigida, a condição transfere o desvio geométrico à estrutura montada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) medir prumo e orientação/torção dos perfis com instrumento aferido, confrontando com as tolerâncias do fabricante e do projeto e mapeando os elementos reprovados; (ii) corrigir os perfis fora de tolerância (realinhamento, recravação ou substituição, conforme orientação do projetista/fabricante), sem forçar a estrutura para acomodar o desvio; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de verificação geométrica, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desnível entre topos exceder a folga de ajuste da estrutura, exigindo retrabalho de arrasamento ou calços fora de especificação',
  texto_fundamentacao_normativa = 'O arrasamento (regularização do topo) e a cota de topo dos elementos devem ficar dentro da tolerância de nivelamento necessária à montagem plana da estrutura de suporte, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e comprovado por nivelamento topográfico. A prática de arrasamento e conferência de cota de topo de fundações é tratada pela NBR 6122 (Projeto e execução de fundações). O critério "Nivelamento dentro da tolerância para a montagem" é requisito verificável de aceitação, pois o plano de topos condiciona o alinhamento e a coplanaridade dos módulos.',
  texto_risco_consequencia = 'Topos fora de cota ou desnivelados além da tolerância comprometem a coplanaridade da estrutura, forçam o uso de calços ou ajustes excessivos e podem impedir a fixação prevista, gerando esforços adicionais e retrabalho de arrasamento após a cura. A condição não corrigida propaga o desnível para toda a mesa/fileira montada sobre os elementos afetados. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar topograficamente as cotas de topo do trecho e mapear os elementos fora da tolerância de montagem; (ii) corrigir o arrasamento/nível dos topos reprovados (rebaixo, complementação ou ajuste conforme o tipo de elemento e orientação do projetista), restabelecendo o plano de montagem; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo nivelamento topográfico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — armadura é elemento estrutural de blocos e sapatas; manter Crítica quando faltarem barras, houver bitola/espaçamento fora do projeto ou cobrimento insuficiente, rebaixando a Maior apenas em desvios pontuais sanáveis antes da concretagem',
  texto_fundamentacao_normativa = 'A armadura dos blocos e sapatas deve reproduzir o detalhamento do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} quanto a bitolas, quantidades, espaçamentos e, sobretudo, cobrimento nominal. Aplicam-se a NBR 6118 (Projeto de estruturas de concreto), que fixa cobrimentos mínimos em função da classe de agressividade ambiental e as regras de detalhamento, e a NBR 6122 (Projeto e execução de fundações). O critério "Bitolas, espaçamentos e cobrimento (blocos e sapatas)" é requisito verificável de aceitação e deve ser conferido antes da concretagem, quando a armadura ainda está exposta.',
  texto_risco_consequencia = 'Armadura com bitola, quantidade ou espaçamento divergentes reduz a capacidade resistente do bloco/sapata; cobrimento insuficiente expõe as barras à corrosão precoce, comprometendo a durabilidade e a segurança estrutural da fundação ao longo da vida útil da usina. Uma vez concretada a peça, a não conformidade torna-se oculta e de correção onerosa. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir, antes da concretagem, bitolas, quantidades, espaçamentos e posicionamento das barras contra o projeto, verificando o cobrimento com espaçadores adequados; (ii) corrigir a armadura fora de conformidade (complementação de barras, reposicionamento e ajuste/recolocação de espaçadores) e reter a liberação da concretagem até o aceite; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a ficha de liberação de armadura assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o fck condiciona a resistência da fundação; manter Crítica quando faltarem corpos de prova, o slump estiver fora da faixa ou houver indício de fck abaixo do especificado, aguardando o rompimento para confirmação',
  texto_fundamentacao_normativa = 'O concreto de blocos e sapatas deve atender à especificação de projeto quanto a fck, consistência (slump) e ao controle de aceitação por corpos de prova moldados e ensaiados. Aplicam-se a NBR 12655 (Concreto de cimento Portland — preparo, controle, recebimento e aceitação), a NBR 5738 (moldagem e cura de corpos de prova) e a NBR 5739 (ensaio de compressão de corpos de prova cilíndricos), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "fck, slump e corpos de prova moldados (NBR 12655)" é requisito verificável de aceitação do lote de concreto.',
  texto_risco_consequencia = 'Concreto sem controle adequado, com slump fora da faixa ou fck abaixo do especificado, resulta em fundação com resistência e durabilidade inferiores às de projeto, elevando o risco de fissuração, recalques e comprometimento estrutural; a ausência de corpos de prova impede a aceitação formal do lote e a rastreabilidade da resistência. Não sanada, a condição consolida um lote de concreto de qualidade não comprovada na fundação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o slump na chegada e moldar/curar/romper os corpos de prova conforme NBR 5738/NBR 5739, recuperando a documentação de aceitação do lote; (ii) para lotes com fck não comprovado ou reprovado, executar ensaios complementares (extração de testemunhos e/ou ensaios não destrutivos) e tratar conforme parecer do projetista quanto à aceitação, reforço ou demolição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de ensaio do concreto, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o ensaio de carga é a comprovação direta do desempenho da fundação; manter Crítica quando exigido em projeto e não realizado, ou quando reprovar frente à carga de trabalho prevista',
  texto_fundamentacao_normativa = 'Quando o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} exigir, deve ser realizado ensaio de carga (estático ou dinâmico) para comprovar a capacidade de carga e o comportamento carga-recalque da fundação. A prova de carga em fundações é prevista pela NBR 6122 (Projeto e execução de fundações), que estabelece quando o ensaio é requerido e como interpretar seus resultados para aceitação. O critério "Estático/dinâmico conforme projeto" é requisito verificável de aceitação e valida em campo as premissas de dimensionamento.',
  texto_risco_consequencia = 'Deixar de realizar o ensaio de carga exigido, ou aceitar elemento reprovado, mantém sem comprovação a capacidade de carga da fundação, admitindo o risco de recalques excessivos ou ruptura sob carregamento de serviço, com comprometimento da estrutura de suporte e dos módulos. Enquanto não realizado, o desempenho da fundação permanece não verificado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e executar o ensaio de carga (estático ou dinâmico) no tipo, quantidade e carga previstos em projeto, com relatório de carga versus recalque/deslocamento; (ii) tratar os elementos reprovados conforme parecer do projetista de fundações (reforço, complementação ou substituição) e ampliar a amostragem no entorno; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de ensaio de carga, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — divergência entre solo encontrado e sondagem invalida a premissa de projeto; manter Crítica até haver reprojeto ou disposição formal do projetista para os elementos afetados',
  texto_fundamentacao_normativa = 'Quando o solo encontrado na execução divergir do previsto na investigação geotécnica (sondagens), a ocorrência deve ser registrada e submetida ao projetista para reprojeto ou disposição formal, não podendo a fundação prosseguir sob premissa geotécnica não confirmada. Aplicam-se a NBR 6122 (Projeto e execução de fundações), que trata da conformidade entre a investigação e as condições reais do subsolo, e a NBR 6484 (sondagens de simples reconhecimento dos solos com SPT), referência da investigação, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Solo divergente da sondagem → reprojeto/disposição registrada" é requisito verificável de aceitação e de gestão do risco geotécnico.',
  texto_risco_consequencia = 'Prosseguir a fundação sobre solo divergente da sondagem, sem reavaliação, adota parâmetros geotécnicos incorretos, podendo resultar em subdimensionamento, recalques diferenciais e ruptura do apoio, além de comprometer os elementos já executados no trecho afetado. Sem o tratamento formal, o desvio geotécnico permanece incorporado à obra e sem rastreabilidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) registrar formalmente a divergência (perfil real, cotas e extensão), paralisando a execução no trecho afetado até parecer técnico; (ii) submeter a ocorrência ao projetista geotécnico/de fundações para reprojeto ou disposição documentada (sondagem complementar, adequação de comprimento/tipo de elemento ou reforço), tratando os elementos já executados conforme a decisão; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o parecer/reprojeto e o registro de disposição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-03' and item_numero = 9;

-- CV-04 (11 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a deficiência das formas (perda de estanqueidade, travamento insuficiente ou fuga de geometria) puder provocar deformação, fuga de nata ou colapso durante a concretagem.',
  texto_fundamentacao_normativa = 'A forma é o molde que impõe a geometria, o prumo e o nível da peça de concreto e deve resistir aos esforços de lançamento e adensamento sem deslocamentos, mantendo estanqueidade para evitar fuga de nata e conservando dimensões conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Aplica-se a NBR 14931 (execução de estruturas de concreto), que estabelece os requisitos de projeto, montagem e conferência das formas e escoramentos antes da concretagem. O critério "Geometria, estanqueidade, travamento e desmoldante" integra o plano de inspeção da obra e constitui requisito verificável de liberação da etapa.',
  texto_risco_consequencia = 'Formas não conferidas quanto a geometria, estanqueidade e travamento podem sofrer deslocamento ou abertura sob a pressão do concreto fresco, gerando peças fora de esquadro, perda de nata com ninhos de concretagem e, no limite, ruína da forma durante o lançamento, com risco à segurança da equipe e retrabalho de demolição e reconcretagem. A permanência da condição mantém ativo o risco até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir geometria, prumo, nível, travamento e escoramento das formas confrontando com o projeto executivo aprovado, vedando juntas para assegurar estanqueidade; (ii) aplicar desmoldante compatível de forma uniforme, sem contaminar a armadura; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspeção da forma, liberando-a formalmente apenas após o atendimento. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — por afetar diretamente a capacidade resistente da peça; manter como Maior apenas se a divergência for pontual, sem repercussão no dimensionamento, mediante aval do projetista estrutural.',
  texto_fundamentacao_normativa = 'A armadura é o elemento que absorve os esforços de tração da peça de concreto armado, e sua bitola, espaçamento, amarração e comprimento de emendas/transpasses são grandezas dimensionadas em projeto; qualquer divergência altera a resistência efetiva do elemento. Aplicam-se a NBR 6118 (projeto de estruturas de concreto), que define o detalhamento e os comprimentos de ancoragem e de traspasse, e a NBR 14931 (execução), que trata do posicionamento e da montagem, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Bitola, espaçamento, amarração e emendas/transpasses" é requisito verificável de aceitação anterior à concretagem.',
  texto_risco_consequencia = 'Armadura com bitola, espaçamento ou traspasses divergentes do projeto reduz a capacidade resistente da peça, podendo levar à fissuração precoce, deformação excessiva e, em situações extremas, à ruptura estrutural, condição de difícil correção após a concretagem por ficar embutida no concreto. A permanência da condição mantém ativo o desvio de armação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir bitola, quantidade, espaçamento e amarração de cada família de barras confrontando com o detalhamento do projeto executivo aprovado; (ii) corrigir posicionamento, refazer amarrações frouxas e ajustar comprimentos de emendas/traspasses aos valores de projeto, submetendo divergências ao projetista estrutural quando necessário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspeção da armação, liberando a peça somente após conformidade. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a insuficiência de cobrimento ocorrer em ambiente de agressividade elevada ou em faces expostas, comprometendo a durabilidade e a proteção da armadura.',
  texto_fundamentacao_normativa = 'O cobrimento é a camada de concreto que protege a armadura contra a corrosão e garante a aderência e a resistência ao fogo, sendo definido em função da classe de agressividade ambiental. Aplica-se a NBR 6118 (projeto de estruturas de concreto), que fixa o cobrimento nominal e o uso de espaçadores para assegurá-lo, em consonância com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Espaçadores adequados em quantidade suficiente" é requisito verificável de aceitação, pois cobrimento deficiente por falta ou má distribuição de espaçadores compromete diretamente a durabilidade da estrutura.',
  texto_risco_consequencia = 'Cobrimento não garantido, por espaçadores insuficientes ou mal distribuídos, expõe a armadura à frente de carbonatação e ao ataque de cloretos, antecipando a corrosão, o lascamento do concreto e a perda de seção resistente das barras ao longo da vida útil da estrutura. A permanência da condição mantém ativo o risco de durabilidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o cobrimento nominal exigido pela classe de agressividade e conferir tipo, altura, quantidade e distribuição dos espaçadores em todas as faces e nas barras de canto; (ii) acrescentar ou reposicionar espaçadores adequados de modo a garantir o afastamento das barras em relação à forma; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e reinspeção antes do lançamento. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver concretagem iniciada sem a liberação formal assinada, por descaracterizar o controle de qualidade e impedir a rastreabilidade da aceitação da etapa.',
  texto_fundamentacao_normativa = 'A liberação formal pré-concretagem é o ato de controle que atesta, por assinatura conjunta da fiscalização e da executora, que formas, armadura, cobrimento e instalações embutidas foram conferidos e estão aptos ao lançamento, garantindo a rastreabilidade da decisão. O critério "Checklist assinado (fiscal + executora) antes do lançamento" integra o plano de inspeção da obra e as boas práticas de gestão da qualidade, sendo condição documental de aceitação prevista para o controle de execução das estruturas de concreto, em coerência com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Trata-se de requisito verificável e obrigatório para o prosseguimento da etapa.',
  texto_risco_consequencia = 'Concretagem lançada sem liberação formal assinada suprime o ponto de verificação que precede o embutimento definitivo da armadura, permitindo que não conformidades de forma, armação ou cobrimento sejam consolidadas no concreto sem registro, o que impede a rastreabilidade e transfere ao concreto endurecido correções de custo elevado. A permanência da condição mantém ativa a lacuna de controle até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instituir e exigir o preenchimento do checklist de liberação pré-concretagem, com conferência de formas, armadura, cobrimento e embutidos, antes de qualquer lançamento; (ii) coletar as assinaturas da fiscalização e da executora e arquivar o documento junto ao dossiê da peça, condicionando a concretagem à liberação; (iii) evidenciar a implantação com registro fotográfico ({{evidencia_foto_correcao}}) e cópia do checklist assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se concreto com abatimento fora da especificação for aceito e lançado, ou rebaixar a Observação se o desvio for corrigido na chegada com recusa do caminhão não conforme.',
  texto_fundamentacao_normativa = 'O ensaio de abatimento (slump test) verifica a consistência do concreto fresco no recebimento, condição associada à trabalhabilidade e ao teor de água, garantindo que o material entregue corresponde ao concreto pedido. Aplicam-se a NBR NM 67 (determinação da consistência pelo abatimento do tronco de cone) e a NBR 12655 (controle e recebimento do concreto), que disciplinam o recebimento por caminhão, em consonância com a especificação de projeto e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Valores conforme pedido; caminhões fora da especificação recusados" é requisito verificável de aceitação no ato da entrega.',
  texto_risco_consequencia = 'Aceitar concreto com abatimento fora do intervalo pedido introduz material com trabalhabilidade inadequada ou excesso de água, o que reduz a resistência e a durabilidade, favorece segregação e ninhos e compromete o adensamento, defeitos que só se manifestam com o concreto já endurecido na estrutura. A permanência da condição mantém ativo o risco de material não conforme incorporado à obra até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar o slump test na chegada de cada caminhão, antes do lançamento, confrontando o resultado com o valor e a tolerância do pedido; (ii) recusar e devolver o caminhão cujo abatimento esteja fora da especificação, vedada a correção por adição de água em obra, e registrar a ocorrência junto à concreteira; (iii) evidenciar o controle com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de ensaios por caminhão, submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a moldagem, a identificação ou a cura dos corpos de prova estiverem comprometidas a ponto de invalidar o controle tecnológico de um lote de concretagem.',
  texto_fundamentacao_normativa = 'Os corpos de prova são as amostras que permitem verificar a resistência à compressão do concreto e aceitar ou rejeitar o lote fornecido; sua frequência de amostragem, moldagem, identificação e cura condicionam a validade do controle tecnológico. Aplicam-se a NBR 12655 (controle e recebimento, que define a frequência de amostragem citada no critério) e a NBR 5738 (procedimento de moldagem e cura dos corpos de prova), em consonância com a especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Frequência NBR 12655; identificação e cura adequadas" é requisito verificável de aceitação do concreto.',
  texto_risco_consequencia = 'Corpos de prova moldados fora da frequência exigida, sem identificação rastreável ou com cura inadequada, produzem resultados de resistência não representativos ou inválidos, impedindo a aceitação segura do concreto e podendo mascarar um lote de baixa resistência já incorporado à estrutura. A permanência da condição mantém ativa a lacuna de controle tecnológico até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) moldar os corpos de prova na frequência definida pela NBR 12655 para o volume e a classe de concretagem, conforme o plano de amostragem da obra; (ii) identificar cada exemplar com peça, data e caminhão e assegurar cura inicial e transporte adequados até o laboratório; (iii) evidenciar o procedimento com registro fotográfico ({{evidencia_foto_correcao}}) e a planilha de moldagem/identificação, submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a altura de lançamento excessiva ou o adensamento deficiente provocarem segregação ou falhas em elementos estruturais de responsabilidade.',
  texto_fundamentacao_normativa = 'O lançamento e o adensamento definem a homogeneidade e a compacidade do concreto na peça; a altura de queda controlada evita segregação e a vibração adequada elimina vazios sem provocar exsudação ou separação dos agregados. Aplica-se a NBR 14931 (execução de estruturas de concreto), que estabelece os requisitos de lançamento e adensamento, em consonância com a especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Altura de lançamento, vibração sem segregação" é requisito verificável de execução da concretagem.',
  texto_risco_consequencia = 'Lançamento de grande altura e adensamento deficiente ou excessivo provocam segregação dos agregados, ninhos de concretagem, vazios internos e exsudação, reduzindo a resistência e a durabilidade da peça e exigindo reparos que nem sempre restabelecem o desempenho estrutural original. A permanência da condição mantém ativo o risco de defeitos internos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) limitar a altura de lançamento e utilizar dispositivos (trombas/calhas) quando necessário, lançando o concreto em camadas compatíveis com o vibrador; (ii) adensar com vibrador de imersão em pontos e tempos adequados, sem vibrar a armadura nem provocar segregação, e revibrar as camadas na interface; (iii) evidenciar a correção da sistemática com registro fotográfico ({{evidencia_foto_correcao}}) e, quando aplicável, reparo das falhas detectadas, submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a junta de concretagem estiver localizada em região de esforços elevados não prevista em projeto ou sem preparo da superfície de retomada.',
  texto_fundamentacao_normativa = 'A junta de concretagem é a interface entre concretagens sucessivas e deve ser posicionada em regiões de menores esforços e ter a superfície preparada (limpeza, remoção de nata e apicoamento) para assegurar a monoliticidade e a transferência de esforços. Aplicam-se a NBR 14931 (execução) e a NBR 6118 (projeto), que orientam a localização e o tratamento das juntas, em consonância com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Localização e preparo conforme projeto" é requisito verificável de execução.',
  texto_risco_consequencia = 'Juntas de concretagem mal localizadas ou sem preparo da superfície criam planos de fraqueza com aderência deficiente entre as camadas, favorecendo infiltração, fissuração e redução da capacidade de transferência de esforços na interface, com prejuízo à estanqueidade e à integridade estrutural. A permanência da condição mantém ativo o plano de descontinuidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) posicionar as juntas conforme o projeto, em regiões de menores esforços, e planejar a sequência de concretagem; (ii) preparar a superfície de retomada com limpeza, remoção da nata superficial, apicoamento e umedecimento (ou ponte de aderência quando especificada) antes da nova concretagem; (iii) evidenciar o tratamento com registro fotográfico ({{evidencia_foto_correcao}}) e reinspeção da junta antes do lançamento subsequente. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em concretagens de grande superfície exposta, clima quente e seco ou peças de responsabilidade, em que a cura deficiente compromete resistência e durabilidade.',
  texto_fundamentacao_normativa = 'A cura mantém a umidade e controla a temperatura do concreto nas primeiras idades, permitindo a hidratação do cimento e o desenvolvimento da resistência e da durabilidade superficial, além de reduzir a fissuração por retração plástica. Aplica-se a NBR 14931 (execução de estruturas de concreto), que estabelece método e prazo mínimo de cura, em consonância com a especificação do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Método e prazo mínimo conforme especificação" é requisito verificável de execução da concretagem.',
  texto_risco_consequencia = 'Cura ausente ou interrompida antes do prazo mínimo provoca perda precoce de água, prejudicando a hidratação do cimento, reduzindo a resistência superficial e a durabilidade e favorecendo a fissuração por retração, defeitos que comprometem o desempenho da peça de forma irreversível. A permanência da condição mantém ativo o déficit de cura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) iniciar a cura logo após o acabamento, adotando o método especificado (umedecimento contínuo, mantas úmidas, lâmina d''água ou membrana), protegendo a superfície do sol e do vento; (ii) manter a cura pelo prazo mínimo especificado, registrando início, método e término; (iii) evidenciar a execução com registro fotográfico ({{evidencia_foto_correcao}}) e o controle de cura da peça, submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 9;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — sempre que resultados de fck aos 28 dias não atingirem o valor de projeto, exigindo análise estrutural; manter como Maior apenas em desvios de 7 dias ainda dentro da evolução esperada de resistência.',
  texto_fundamentacao_normativa = 'O fck é a resistência característica à compressão que fundamenta o dimensionamento da estrutura; a conferência dos resultados dos ensaios contra o valor de projeto valida a aceitação do concreto executado. Aplicam-se a NBR 12655 (controle, recebimento e critérios de aceitação do concreto) e a NBR 5739 (ensaio de compressão dos corpos de prova), em consonância com o fck especificado no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "7/28 dias × projeto; não conformidade → análise estrutural" é requisito verificável de aceitação e disciplina o encaminhamento em caso de resultado insuficiente.',
  texto_risco_consequencia = 'Resultados de fck inferiores ao valor de projeto indicam concreto com resistência abaixo do previsto no dimensionamento, o que reduz a margem de segurança da peça e pode exigir reforço, restrição de uso ou até demolição, decisões que dependem de análise estrutural específica e impactam custo e cronograma. A permanência da condição mantém ativa a incerteza sobre a segurança da peça até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir sistematicamente os relatórios de ruptura de 7 e 28 dias contra o fck de projeto, aplicando os critérios de aceitação da NBR 12655; (ii) diante de resultado não conforme, acionar o projetista estrutural para análise (revisão do dimensionamento, ensaios complementares como extração de testemunhos/esclerometria e, se necessário, reforço ou demolição), com registro das tratativas; (iii) evidenciar a conferência e o encaminhamento com registro fotográfico ({{evidencia_foto_correcao}}) e os laudos correspondentes, submetendo à reinspeção. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 10;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando bicheiras ou segregações expuserem armadura ou atingirem seção resistente relevante, condicionando o reparo à avaliação estrutural.',
  texto_fundamentacao_normativa = 'Bicheiras (ninhos de concretagem) e segregações são falhas que reduzem a seção efetiva, expõem a armadura e criam caminhos de infiltração, exigindo mapeamento e tratamento por procedimento de reparo tecnicamente definido e aprovado. Na ausência de norma específica de certeza para a técnica de reparo, a fundamentação apoia-se no critério do item, nas boas práticas de recuperação estrutural e no procedimento de reparo aprovado, em consonância com a especificação e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Bicheiras/segregações com procedimento de reparo aprovado" é requisito verificável de aceitação da peça acabada.',
  texto_risco_consequencia = 'Bicheiras e segregações não mapeadas ou tratadas sem procedimento aprovado mantêm a armadura exposta e a seção reduzida, favorecendo corrosão, infiltração e perda localizada de capacidade resistente, além de reparos improvisados que podem se descolar e não restabelecer o desempenho da peça. A permanência da condição mantém ativa a falha estrutural até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear e registrar todas as bicheiras e segregações, classificando extensão, profundidade e exposição de armadura; (ii) tratar cada falha conforme procedimento de reparo aprovado (remoção do concreto solto até o material são, limpeza e proteção da armadura, aplicação de graute/argamassa de reparo compatível e cura), submetendo os casos de maior gravidade à avaliação estrutural; (iii) evidenciar o reparo com registro fotográfico ({{evidencia_foto_correcao}}) antes, durante e depois, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-04' and item_numero = 11;

-- CV-05 (9 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de traçado ou de declividade inverter o sentido de escoamento ou direcionar águas para plataformas, taludes ou fundações desprotegidas.',
  texto_fundamentacao_normativa = 'A implantação da drenagem definitiva deve reproduzir fielmente o traçado, as seções transversais e as declividades longitudinais fixados em projeto, condição verificável por levantamento topográfico. A funcionalidade hidráulica do sistema depende da manutenção das declividades mínimas de escoamento e das cotas de fundo previstas; qualquer alteração compromete a capacidade de vazão e a autolimpeza dos dispositivos. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define geometria, greides e sentido de escoamento, integrando o plano de inspeção da obra como requisito de aceitação da etapa. O critério "Traçado, seções e declividades conferidos" constitui parâmetro verificável de conformidade.',
  texto_risco_consequencia = 'Drenagem implantada fora do traçado, das seções ou das declividades de projeto reduz ou anula a capacidade de escoamento, favorecendo empoçamento, refluxo e concentração indevida de águas pluviais sobre plataformas, taludes e fundações, com risco de erosão, saturação de solos e instabilização de estruturas adjacentes. A permanência da condição mantém o sistema hidraulicamente ineficaz e propaga o desvio a jusante até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente traçado, seções e declividades do trecho, confrontando cotas de fundo e greides com o projeto executivo aprovado; (ii) corrigir a geometria implantada — reassentamento, reperfilamento ou reexecução do dispositivo, conforme o caso — restabelecendo as declividades e o sentido de escoamento previstos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo levantamento topográfico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em trechos inclinados quando a ausência de ancoragem permitir deslizamento das canaletas ou quando falhas de rejunte causarem infiltração no talude de apoio.',
  texto_fundamentacao_normativa = 'As canaletas devem ser assentadas alinhadas, com juntas devidamente rejuntadas e vedadas e, em trechos inclinados, ancoradas conforme detalhe de projeto, de modo a garantir estanqueidade e estabilidade do conduto. Juntas abertas ou mal vedadas permitem fuga de água para o subleito, e a falta de ancoragem em declive expõe as peças a escorregamento sob o próprio peso e a esforço hidrodinâmico. Aplicam-se as especificações do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as boas práticas de assentamento de dispositivos de drenagem. O critério "Assentamento, rejunte e ancoragem em trechos inclinados" integra o plano de inspeção como requisito verificável de aceitação.',
  texto_risco_consequencia = 'Canaletas desalinhadas, com juntas abertas ou sem ancoragem em declive, provocam vazamentos que saturam e erodem o solo de apoio, além de permitirem o deslocamento das peças, com ruptura da linha de escoamento e formação de caminhos preferenciais de erosão no talude. A permanência da condição compromete a estanqueidade e a estabilidade do sistema até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realinhar as canaletas e refazer os rejuntes com material e vedação adequados, garantindo continuidade e estanqueidade das juntas; (ii) executar ou reforçar a ancoragem das peças nos trechos inclinados conforme detalhe de projeto, prevenindo deslizamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e verificação de estanqueidade, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando dimensões insuficientes reduzirem a capacidade hidráulica do bueiro ou quando tampas inadequadas comprometerem a segurança de trânsito ou a acessibilidade para manutenção.',
  texto_fundamentacao_normativa = 'As caixas de passagem e os bueiros devem ser executados com as dimensões internas, as tampas e as alas de entrada e saída previstas em projeto, assegurando capacidade hidráulica, encaminhamento adequado do fluxo e condições de inspeção e manutenção. As alas orientam a transição do escoamento e protegem as extremidades contra erosão, enquanto tampas corretamente dimensionadas garantem segurança e acesso. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define geometria, cotas e detalhamento dos dispositivos. O critério "Dimensões, tampas e alas conforme projeto" constitui requisito verificável de aceitação integrante do plano de inspeção da obra.',
  texto_risco_consequencia = 'Caixas ou bueiros com dimensões, tampas ou alas em desacordo com o projeto restringem a vazão e favorecem transbordamento, assoreamento e erosão nas bocas dos dispositivos, além de criar riscos de acidente por tampas inadequadas e de dificultar a manutenção do sistema. A permanência da condição mantém o ponto como estrangulamento hidráulico e foco de deterioração. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir dimensões internas, cotas de fundo, tampas e alas dos dispositivos contra o projeto executivo aprovado, identificando as não conformidades; (ii) corrigir os elementos divergentes — adequação de dimensões, substituição/assentamento de tampas e execução ou reparo das alas — restabelecendo a geometria e a proteção previstas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e conferência dimensional, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência ou subdimensionamento do dissipador expuser fundações, aterros ou o corpo estradal à erosão regressiva a partir do ponto de deságue.',
  texto_fundamentacao_normativa = 'Os dissipadores de energia devem ser implantados nos pontos de deságue conforme o detalhe de projeto, com a função de reduzir a velocidade e a energia do fluxo antes do lançamento no terreno natural ou no corpo receptor, prevenindo erosão a jusante. A eficiência do dispositivo depende da geometria, do tipo de proteção e do posicionamento definidos em projeto. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que detalha os dissipadores nos deságues, e as boas práticas de proteção contra erosão em drenagem. O critério "Nos deságues, conforme detalhe do projeto" integra o plano de inspeção como requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência, o posicionamento incorreto ou o subdimensionamento dos dissipadores permite o lançamento de fluxo de alta energia diretamente sobre o terreno, deflagrando erosão regressiva, formação de crateras e solapamento a partir do ponto de deságue, com risco de comprometimento de aterros, taludes e fundações próximas. A permanência da condição mantém ativo o processo erosivo a cada evento de chuva. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a existência, o posicionamento e a geometria dos dissipadores em cada deságue, confrontando com o detalhe do projeto executivo aprovado; (ii) implantar ou complementar os dissipadores em falta e recompor eventuais erosões já iniciadas a jusante, restabelecendo a proteção prevista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos deságues protegidos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de proteção superficial estiver associada a talude de altura ou inclinação relevante, com sinais de instabilização ou de erosão já em curso.',
  texto_fundamentacao_normativa = 'A proteção superficial dos taludes — por enrocamento, biomanta, vegetação ou outra solução definida em projeto — deve ser executada para dissipar o impacto das águas pluviais, reduzir o carreamento de partículas e proteger a face contra erosão laminar e concentrada. O tipo, a extensão e o método de proteção são estabelecidos em função da natureza do solo e da exposição do talude. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que especifica a proteção superficial, e as boas práticas de estabilização e revestimento de taludes. O critério "Enrocamento/biomanta/vegetação conforme projeto" constitui requisito verificável de aceitação do plano de inspeção.',
  texto_risco_consequencia = 'Taludes sem a proteção superficial especificada ficam expostos à ação direta das chuvas, com erosão laminar, formação de sulcos e ravinas, perda de material e progressiva instabilização da face, podendo evoluir para escorregamentos que atingem dispositivos de drenagem, plataformas e estruturas próximas. A permanência da condição acelera a degradação do talude a cada evento pluvial. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os trechos de talude sem a proteção especificada e avaliar erosões já iniciadas; (ii) executar a proteção superficial conforme projeto — enrocamento, biomanta, hidrossemeadura/vegetação ou solução equivalente prevista — recompondo previamente o material erodido; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da face protegida, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando as erosões ou ravinas atingirem a base de taludes, dispositivos de drenagem ou a plataforma da via, indicando evolução para solapamento ou ruptura.',
  texto_fundamentacao_normativa = 'O sistema deve permanecer isento de erosões e ravinas, condição a ser verificada por inspeção após chuvas significativas, com o respectivo registro. A inspeção periódica pós-chuva é o mecanismo de detecção precoce de falhas de escoamento e de início de processos erosivos, permitindo intervenção antes da evolução para danos maiores. Fundamenta-se no critério do próprio item, nas boas práticas de manutenção de drenagem e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto às condições de escoamento previstas. O critério "Inspeção após chuvas significativas registrada" integra o plano de inspeção como requisito verificável de aceitação e monitoramento.',
  texto_risco_consequencia = 'A presença de erosões e ravinas, ou a ausência de inspeção registrada após chuvas significativas, indica falha de escoamento não detectada e permite que o processo erosivo progrida para sulcos profundos, solapamento de taludes e comprometimento de dispositivos de drenagem e da plataforma, elevando o custo e a complexidade da recuperação. A permanência da condição mantém o dano evoluindo sem controle a cada precipitação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear e caracterizar as erosões e ravinas existentes, identificando as causas de concentração de fluxo; (ii) recompor as áreas erodidas e corrigir a origem do desvio de escoamento, implantando/ajustando dispositivos e protegendo a superfície, e instituir rotina de inspeção pós-chuva com registro; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o respectivo relatório de inspeção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o assoreamento reduzir de forma significativa a seção de escoamento de canaletas e caixas, comprometendo a vazão em evento de chuva.',
  texto_fundamentacao_normativa = 'O sistema deve permanecer desassoreado, com a limpeza de canaletas e caixas mantida em dia, preservando a seção hidráulica de projeto e a capacidade de escoamento. O acúmulo de sedimentos, detritos e vegetação reduz a seção útil e a velocidade de fluxo, comprometendo a autolimpeza e a vazão dos dispositivos. Fundamenta-se no critério do item, nas boas práticas de manutenção preventiva de drenagem e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto às seções de escoamento previstas. O critério "Limpeza de canaletas e caixas em dia" integra o plano de inspeção como requisito verificável de conservação do sistema.',
  texto_risco_consequencia = 'Canaletas e caixas assoreadas têm a seção de escoamento reduzida, o que diminui a vazão e provoca transbordamento, refluxo e lançamento de águas em pontos não previstos durante as chuvas, favorecendo empoçamento e erosão no entorno dos dispositivos. A permanência da condição agrava o acúmulo e reduz progressivamente a eficiência hidráulica do sistema. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar canaletas, caixas e bueiros, identificando os pontos e o grau de assoreamento; (ii) executar a limpeza e a remoção dos sedimentos e detritos, restabelecendo a seção plena de escoamento, e instituir/registrar cronograma de manutenção preventiva; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos dispositivos desassoreados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a transição deficiente entre a drenagem provisória e a definitiva gerar ponto de acúmulo capaz de erodir aterros ou saturar a plataforma.',
  texto_fundamentacao_normativa = 'A drenagem definitiva deve integrar-se à drenagem provisória de forma contínua, com transições que não gerem pontos de acúmulo, degraus hidráulicos ou descontinuidades no escoamento durante as fases de obra. Uma transição mal executada interrompe o fluxo e concentra águas em pontos não protegidos. Fundamenta-se no critério do item, no planejamento de drenagem da obra e nas boas práticas de compatibilização entre sistemas provisório e definitivo, em consonância com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Transição sem pontos de acúmulo" integra o plano de inspeção como requisito verificável de aceitação da interface entre sistemas.',
  texto_risco_consequencia = 'A transição inadequada entre a drenagem provisória e a definitiva cria pontos de acúmulo e descontinuidade de escoamento, provocando empoçamento, infiltração e erosão localizada em áreas ainda em obra, com risco de saturação de aterros e danos aos serviços já executados. A permanência da condição mantém o ponto de acúmulo ativo enquanto persistir a interface entre os sistemas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) percorrer as interfaces entre a drenagem provisória e a definitiva, localizando os pontos de acúmulo e as descontinuidades de escoamento; (ii) executar as adequações de transição — regularização de cotas, conexões e proteções — assegurando continuidade do fluxo até o sistema definitivo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das transições regularizadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 8;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — as travessias sob vias envolvem carregamento de tráfego sobre a tubulação; recobrimento insuficiente ou proteção inadequada pode levar à ruptura do conduto e ao colapso do pavimento.',
  texto_fundamentacao_normativa = 'As travessias sob vias, executadas por tubos ou galerias, devem observar o recobrimento mínimo e a proteção estrutural definidos em projeto, de modo a suportar as cargas de tráfego e distribuí-las sem transmitir esforços excessivos ao conduto. O recobrimento e a envoltória de proteção condicionam a integridade da travessia e a estabilidade do pavimento sobrejacente. Aplica-se o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define diâmetros, cotas, recobrimento e detalhes de proteção, complementado pelas boas práticas de assentamento de tubulações sob carga de tráfego. O critério "Tubos/galerias com recobrimento e proteção" constitui requisito verificável de aceitação integrante do plano de inspeção.',
  texto_risco_consequencia = 'Travessias com recobrimento insuficiente ou proteção inadequada expõem o conduto às cargas dinâmicas do tráfego, com risco de deformação, fissuração e ruptura da tubulação, seguidas de infiltração, formação de vazios e recalque ou colapso localizado do pavimento sobre a travessia, com risco à segurança viária. A permanência da condição mantém a travessia sujeita a falha a cada solicitação de tráfego. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o recobrimento efetivo e as condições de proteção da tubulação/galeria na travessia, confrontando com o projeto executivo aprovado; (ii) corrigir a não conformidade — complementação de recobrimento, execução da envoltória/proteção prevista ou readequação do assentamento — restabelecendo a capacidade de suporte à carga de tráfego; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e conferência de cotas de recobrimento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-05' and item_numero = 9;

-- CV-06 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de gabarito, projeção ou prumo dos chumbadores inviabilizar o encaixe da base metálica ou exigir alargamento de furação da placa de base',
  texto_fundamentacao_normativa = 'A locação dos chumbadores define a interface entre a fundação e a estrutura metálica de suporte e deve reproduzir o gabarito, a projeção e o prumo estabelecidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, dentro das tolerâncias de montagem ali fixadas. O critério "Gabarito, projeção e prumo dentro das tolerâncias" integra o plano de inspeção e constitui requisito verificável de aceitação, pois a conferência do posicionamento dos chumbadores por gabarito de montagem e instrumento de prumo é boa prática consolidada de montagem de estruturas metálicas e condiciona a compatibilidade com a placa de base especificada.',
  texto_risco_consequencia = 'Chumbadores locados fora do gabarito, da projeção ou do prumo impedem o assentamento correto da base metálica, forçando ajustes de campo como alargamento de furos, calços improvisados ou reposicionamento, que reduzem a área de contato e a capacidade de ancoragem previstas em projeto e comprometem a estabilidade da estrutura de suporte. A permanência da condição mantém a base em desconformidade geométrica até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir com gabarito de montagem e instrumento de prumo o posicionamento, a projeção e o alinhamento de cada chumbador, confrontando com o projeto executivo aprovado; (ii) corrigir os chumbadores fora de tolerância pelo método aprovado pelo projetista (reposicionamento, reancoragem química ou substituição), vedado o simples entortamento em campo; (iii) evidenciar a correção com registro fotográfico e nova conferência de gabarito ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desnível das bases exceder a folga de grauteamento prevista ou comprometer o nivelamento do equipamento ou estrutura apoiada',
  texto_fundamentacao_normativa = 'O nivelamento das bases, materializado por placas de nivelamento e cotas de topo, deve atender ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, garantindo o plano de apoio correto para a estrutura metálica de suporte. O critério "Placas de nivelamento e cotas conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação, sendo a conferência das cotas de topo por nível ou levantamento topográfico e a verificação das placas de nivelamento práticas consagradas de montagem que asseguram a transferência uniforme de cargas à fundação.',
  texto_risco_consequencia = 'Bases fora de nível transferem carga de forma excêntrica e concentrada à fundação, induzem esforços não previstos na estrutura metálica e no grauteamento e podem provocar desaprumo do conjunto apoiado, com retrabalho de reassentamento e sobrecusto. A permanência da condição mantém o plano de apoio irregular até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar por nível óptico ou topografia as cotas de topo de cada base e conferir a presença, o assentamento e a espessura das placas de nivelamento contra o projeto; (ii) corrigir o nivelamento reposicionando ou ajustando as placas de nivelamento e restabelecendo as cotas de projeto antes do grauteamento; (iii) evidenciar a correção com registro fotográfico e novo levantamento de cotas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver vazios, segregação ou cura deficiente que reduzam o contato base-fundação ou a resistência do graute abaixo da especificada',
  texto_fundamentacao_normativa = 'O grauteamento preenche o espaço entre a base metálica e a fundação e é responsável por transmitir integralmente as cargas ao concreto; deve empregar material aprovado e obedecer ao preparo, lançamento e cura definidos na especificação técnica do fabricante e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Material aprovado, preparo e cura corretos" integra o plano de inspeção e constitui requisito verificável de aceitação, pois o cumprimento da ficha técnica do graute (relação água/pó, tempo de utilização, moldagem de corpos de prova e cura) é boa prática que assegura o desempenho e a durabilidade da ligação.',
  texto_risco_consequencia = 'Graute com material não aprovado, preparo incorreto ou cura deficiente resulta em vazios, segregação e resistência abaixo da especificada, criando apoio parcial que concentra tensões, favorece a fissuração e a corrosão sob a base e reduz a capacidade de transferência de carga à fundação. A permanência da condição mantém a ligação estrutural comprometida até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o certificado e a validade do graute, a conformidade do traço/preparo com a ficha técnica e os registros de cura e de corpos de prova; (ii) remover e refazer o grauteamento com material aprovado nos trechos com vazios, segregação ou resistência insuficiente, seguindo integralmente a especificação do fabricante; (iii) evidenciar a correção com registro fotográfico e resultados de ensaio de resistência ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de requisito de ancoragem estrutural; rebaixar a Maior apenas quando a divergência for pontual, sem torque abaixo do mínimo, e integralmente sanável por reaperto controlado',
  texto_fundamentacao_normativa = 'O torque de ancoragem garante a protensão e o travamento previstos para os chumbadores, condição essencial à estabilidade da base metálica sob cargas e vibrações. A aplicação deve seguir o mapa de torque e os valores especificados em projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e na recomendação do fabricante do sistema de ancoragem. O critério "Mapa de torque com torquímetro calibrado" integra o plano de inspeção e constitui requisito verificável de aceitação, sendo o uso de torquímetro com calibração vigente e o registro individualizado por parafuso boas práticas que asseguram a rastreabilidade e a uniformidade do aperto.',
  texto_risco_consequencia = 'Torque insuficiente, excessivo ou aplicado sem torquímetro calibrado compromete a protensão de projeto: o aperto baixo permite folga, afrouxamento sob vibração e perda de ancoragem, enquanto o excessivo pode escoar ou romper o chumbador, em ambos os casos ameaçando a estabilidade da estrutura de suporte. A permanência da condição mantém a ancoragem sem garantia de desempenho até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a validade da calibração do torquímetro e conferir o mapa de torque, identificando os parafusos sem registro ou fora do valor especificado; (ii) reaplicar o torque conforme sequência e valores de projeto com instrumento calibrado, substituindo os chumbadores que apresentem sinais de escoamento ou dano; (iii) evidenciar a correção com registro fotográfico e mapa de torque atualizado e assinado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a área danificada for extensa, expuser o aço-base ou situar-se em região crítica de solicitação ou de exposição ambiental agressiva',
  texto_fundamentacao_normativa = 'A camada de galvanização protege a estrutura metálica de suporte contra a corrosão, e danos localizados de manuseio, transporte ou solda devem ser reparados de modo a restabelecer a continuidade protetiva. Aplicam-se a NBR ISO 1461 (revestimentos de zinco por imersão a quente em produtos de aço e ferro fundido) e a especificação de projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que orientam os critérios de aceitação e de reparo do revestimento. O critério "Danos tratados com produto especificado" integra o plano de inspeção e constitui requisito verificável de aceitação, exigindo o uso de tinta rica em zinco ou produto de reparo compatível, aplicado sobre superfície preparada.',
  texto_risco_consequencia = 'Galvanização danificada e não retocada expõe o aço-base à corrosão, que progride sob a camada íntegra adjacente, reduz a seção resistente e a vida útil da estrutura de suporte e pode migrar para as ligações e pontos de ancoragem. A permanência da condição mantém ativo o processo corrosivo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear os pontos de galvanização danificada e verificar o produto de reparo aprovado e sua compatibilidade com o revestimento original; (ii) preparar a superfície (limpeza, remoção de óxidos e definição da rugosidade) e aplicar o produto rico em zinco na espessura especificada, respeitando as sobreposições; (iii) evidenciar a correção com registro fotográfico antes e depois e, quando exigido, medição de espessura de camada ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio dimensional comprometer o alinhamento, o prumo ou o encaixe com estruturas e equipamentos subsequentes',
  texto_fundamentacao_normativa = 'O controle dimensional confirma que a estrutura metálica de suporte foi fabricada e montada conforme a geometria, os alinhamentos e as cotas do projeto, verificação amparada por relatório topográfico. Aplicam-se a NBR 8800 (projeto de estruturas de aço e mistas de aço e concreto), no que se refere às tolerâncias de fabricação e montagem, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Conforme projeto e relatório topográfico" integra o plano de inspeção e constitui requisito verificável de aceitação, sendo a conferência de vãos, prumos, níveis e alinhamentos por topografia a prática que assegura a compatibilidade com as interfaces subsequentes.',
  texto_risco_consequencia = 'Estrutura de suporte fora das dimensões, prumos ou alinhamentos de projeto compromete o encaixe com equipamentos e estruturas subsequentes, podendo exigir adaptações de campo, esforços não previstos nas ligações e retrabalho de remontagem, com sobrecusto e atraso de cronograma. A permanência da condição mantém ativo o desvio geométrico até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente vãos, cotas, prumos e alinhamentos da estrutura, confrontando com o projeto executivo aprovado e as tolerâncias aplicáveis; (ii) corrigir os desvios pelo método aprovado pela engenharia (reposicionamento, reforço ou substituição de elemento), restabelecendo o atendimento ao projeto; (iii) evidenciar a correção com registro fotográfico e novo relatório topográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-06' and item_numero = 6;

-- CV-07 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando rampas acima do máximo, raios de curva reduzidos ou largura insuficiente comprometerem a segurança do tráfego de veículos e equipamentos pesados.',
  texto_fundamentacao_normativa = 'A geometria da via — largura da plataforma, greide, rampas máximas e raios de curva — governa a circulação segura e a trafegabilidade de veículos e equipamentos, condição verificada por levantamento topográfico confrontado com o traçado de projeto. Os parâmetros geométricos devem reproduzir o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as boas práticas de engenharia viária, que dimensionam rampas e curvas em função das dimensões e do desempenho dos veículos de operação. O critério "Larguras, rampas máximas e curvas verificadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Vias executadas com rampas superiores ao máximo admissível, curvas de raio reduzido ou largura insuficiente dificultam a manobra e o cruzamento de veículos, elevando o risco de tombamento, colisão e saída de pista, além de acelerar o desgaste da plataforma. A permanência da condição mantém ativo o desvio geométrico e a exposição ao risco até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente greide, largura, rampas e raios de curva do trecho, confrontando com o projeto executivo aprovado; (ii) corrigir a geometria da plataforma e do greide (regularização, corte ou aterro controlado, conforme o caso), restabelecendo o atendimento aos parâmetros de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo levantamento topográfico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a deficiência de espessura ou o emprego de material fora de especificação comprometer a trafegabilidade de vias e pátios de acesso a operações essenciais.',
  texto_fundamentacao_normativa = 'O revestimento primário deve ser executado com material dentro da faixa granulométrica especificada e na espessura compactada de projeto, garantindo a capacidade de suporte e a durabilidade da via, verificação feita por sondagens/poços de controle e conferência do material aplicado. O material e a espessura devem atender à especificação técnica da obra e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Material e espessura compactada conforme especificação" integra o plano de inspeção e constitui requisito verificável de aceitação da camada.',
  texto_risco_consequencia = 'Revestimento primário com espessura inferior à especificada ou com material inadequado apresenta baixa capacidade de suporte, favorecendo a formação de trilhas de roda, buracos e atoleiros e a deterioração acelerada da via sob tráfego. A permanência da condição mantém a camada fora de conformidade e sujeita a rupturas localizadas até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a espessura compactada por poços/sondagens e conferir a procedência e a granulometria do material aplicado; (ii) complementar a espessura com material especificado e recompactar a camada, ou substituir o material não conforme, conforme o caso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novas medições de espessura, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o grau de compactação ficar abaixo do especificado em trechos de tráfego pesado ou sobre tubulações e estruturas enterradas.',
  texto_fundamentacao_normativa = 'A camada da via deve atingir o grau de compactação (GC) mínimo definido em projeto, entendido como a relação entre a massa específica seca obtida em campo e a massa específica seca máxima de laboratório determinada no ensaio de compactação Proctor (NBR 7182), comprovada por ensaios de densidade in situ. O GC mínimo é definido pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "GC conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação da compactação.',
  texto_risco_consequencia = 'Compactação deficiente, com GC abaixo do especificado, reduz a capacidade de suporte e a estabilidade da via, favorecendo recalques diferenciais, deformações permanentes e a formação de buracos sob tráfego, além de comprometer a proteção de estruturas enterradas. A permanência da condição mantém a camada com desempenho estrutural inferior ao previsto até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir os ensaios de densidade in situ nos pontos reprovados e mapear a extensão do trecho não conforme; (ii) recompactar a camada com controle de umidade e energia adequados (escarificação e nova compactação, se necessário) até atingir o GC de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novos relatórios de ensaio aprovados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior ou Crítica quando a ausência de escoamento provocar empoçamento sobre a plataforma, erosão da via ou solapamento de taludes adjacentes.',
  texto_fundamentacao_normativa = 'Os dispositivos de drenagem lateral — sarjetas, valetas e leiras — devem estar conformados e desobstruídos, com caimento contínuo que conduza as águas pluviais a um ponto de saída, protegendo a plataforma contra saturação e erosão. A concepção e o direcionamento devem atender ao projeto de drenagem da obra (projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}) e às boas práticas de drenagem de vias. O critério "Sarjetas/leiras direcionando água" integra o plano de inspeção e constitui requisito verificável de aceitação da drenagem.',
  texto_risco_consequencia = 'Drenagem lateral inoperante ou mal direcionada permite o empoçamento e a infiltração da água pluvial na plataforma, causando saturação e perda de capacidade de suporte, erosão de bordos e taludes e a formação de atoleiros e buracos. A permanência da condição mantém a via exposta à ação erosiva das chuvas até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) desobstruir e reconformar sarjetas, valetas e leiras, restabelecendo seção e caimento contínuos; (ii) redirecionar o escoamento a dispositivo de saída adequado (bueiro, caixa ou descida), eliminando pontos de empoçamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), preferencialmente com verificação do escoamento em teste ou após chuva, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em cruzamentos, aproximações de frentes de operação e trechos de conflito veículo-pedestre, onde a falta de sinalização eleva o risco de colisão e atropelamento.',
  texto_fundamentacao_normativa = 'A sinalização viária — placas de regulamentação de velocidade, de preferência e de advertência — deve estar implantada nos pontos de decisão para ordenar o tráfego interno e prevenir acidentes, em conformidade com o plano de sinalização da obra e em interface com o requisito ST-09 (sinalização e segurança do trabalho). O tipo, a mensagem e o posicionamento das placas seguem o projeto de sinalização aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as boas práticas de segurança viária. O critério "Placas de velocidade, preferência e advertência" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência ou a implantação incompleta da sinalização deixa condutores sem orientação sobre velocidade, preferência e riscos do trecho, favorecendo o excesso de velocidade, colisões em cruzamentos e atropelamentos em áreas de circulação de pessoas. A permanência da condição mantém a via operando sem os controles de segurança previstos até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a sinalização existente com o plano de sinalização e o levantamento de pontos críticos, identificando as placas faltantes ou mal posicionadas; (ii) implantar e fixar as placas de velocidade, preferência e advertência nos pontos de decisão, garantindo visibilidade e legibilidade, em articulação com a frente ST-09; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das placas instaladas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior ou Crítica quando atoleiros, buracos ou nuvens de poeira interromperem rotas de emergência ou de operações essenciais, ou comprometerem a visibilidade e a saúde.',
  texto_fundamentacao_normativa = 'A via deve ser objeto de manutenção conservativa contínua, com correção tempestiva de atoleiros e buracos no período chuvoso e umectação para controle de poeira no período seco, preservando a trafegabilidade e as condições de segurança. As rotinas e frequências devem seguir o plano de manutenção de vias da obra e as boas práticas de conservação, alinhadas ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Atoleiros/buracos corrigidos; umectação no seco" integra o plano de inspeção e constitui requisito verificável de conservação da via.',
  texto_risco_consequencia = 'A falta de manutenção deixa a via com atoleiros e buracos no período chuvoso, comprometendo a trafegabilidade, danificando veículos e podendo interromper rotas críticas, enquanto a ausência de umectação no período seco gera nuvens de poeira que reduzem a visibilidade e afetam a saúde dos trabalhadores. A permanência da condição mantém a via em estado inadequado de conservação até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) corrigir atoleiros e buracos com remoção do material saturado, reposição de material adequado e recompactação do ponto; (ii) implantar e cumprir rotina de umectação da via no período seco, com registro da frequência, e programar a manutenção conservativa periódica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos trechos recuperados e da umectação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-07' and item_numero = 6;

-- CV-08 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desalinhamento ou o engastamento insuficiente dos mourões comprometer a estabilidade do cercamento em trechos que funcionem como barreira física de segurança ou no perímetro de subestação',
  texto_fundamentacao_normativa = 'O alinhamento, o prumo, o espaçamento e a profundidade de engastamento dos mourões definem a estabilidade e a geometria do cercamento, sendo o mourão o elemento que transfere aos apoios os esforços de tensionamento das telas e a ação do vento. Na ausência de norma específica que fixe estes parâmetros para este tipo de fechamento, a aceitação apoia-se no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, nas especificações do fabricante do sistema de cercamento e nas boas práticas de execução. O critério "Espaçamento e engastamento conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Mourões fora de alinhamento, sem prumo ou com engastamento inferior ao especificado reduzem a rigidez do conjunto, permitindo flechas excessivas, afrouxamento das telas e, no limite, tombamento de trechos do cercamento sob vento ou esforço, fragilizando a barreira física do canteiro e o controle de acesso. A permanência da condição mantém ativo o desvio estrutural até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir alinhamento, prumo, espaçamento e profundidade de engastamento dos mourões do trecho, confrontando com o projeto executivo aprovado e a especificação do sistema; (ii) recompor os mourões em desvio — reprumar, reforçar o engastamento ou reexecutar a fundação/chumbamento conforme o caso — restabelecendo a geometria de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-08' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de tensionamento ou de amarrações permitir a abertura de vãos que anulem a função de barreira do cercamento, sobretudo em perímetro de área restrita ou de subestação',
  texto_fundamentacao_normativa = 'O tensionamento adequado das telas e a completude das amarrações aos mourões e aos arames de contorno (superior, inferior e intermediários) garantem que o pano de tela permaneça esticado, contínuo e sem vãos, cumprindo a função de fechamento e delimitação do perímetro. Na ausência de norma específica que discipline estes parâmetros para este sistema, a verificação apoia-se no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, nas instruções do fabricante e nas boas práticas de montagem. O critério "Tensionamento e amarrações completas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Telas frouxas ou com amarrações faltantes formam barrigas, folgas e vãos que comprometem a delimitação do perímetro, facilitam a transposição e a intrusão e aceleram a deterioração da malha por fadiga e corrosão nos pontos soltos, reduzindo a vida útil do cercamento. A permanência da condição mantém a barreira física deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reinspecionar o tensionamento dos panos de tela e conferir a presença e o aperto de todas as amarrações aos mourões e aos arames de contorno; (ii) retensionar a malha e completar ou refazer as amarrações faltantes ou frouxas, eliminando folgas e vãos ao longo do trecho; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-08' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falha de travamento, de fechadura ou de prumo comprometer o controle de acesso da portaria, a rota de emergência ou o fechamento de área restrita/subestação',
  texto_fundamentacao_normativa = 'O portão instalado com prumo, alinhamento das folhas, batentes/travamentos e fechaduras operantes assegura o funcionamento como ponto de controle de acesso e como parte contínua da barreira do perímetro. Na ausência de norma específica para este componente, a aceitação apoia-se no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, na especificação do conjunto (ferragens e fechaduras) e nas boas práticas de instalação, verificando-se a operação real de abertura, fechamento e travamento. O critério "Prumo, travamento e fechaduras" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Portões fora de prumo, com folhas desalinhadas, travamento deficiente ou fechaduras inoperantes comprometem o controle de acesso e a integridade do perímetro, permitindo entrada não autorizada, além de risco de emperramento ou de queda das folhas por mau assentamento de dobradiças e roldanas, com dano ao conjunto e risco às pessoas. A permanência da condição mantém o ponto de acesso vulnerável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar prumo, alinhamento e nivelamento das folhas, o funcionamento de dobradiças/roldanas e batentes e o acionamento de travas e fechaduras; (ii) ajustar ou reinstalar o portão — regular ferragens, corrigir prumo e substituir travamentos ou fechaduras defeituosos — assegurando abertura, fechamento e travamento plenos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste funcional em reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-08' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência ou descontinuidade da equipotencialização/aterramento da cerca no entorno de subestação configura risco elétrico direto; manter Crítica enquanto persistir e não rebaixar sem medição de continuidade e de resistência de aterramento aprovada',
  texto_fundamentacao_normativa = 'A equipotencialização e o aterramento do cercamento metálico no entorno de subestação limitam as tensões de passo e de toque que podem surgir na cerca em condição de falta à terra, evitando que ela se torne um caminho de corrente perigoso às pessoas. Aplicam-se a NBR 15751 (sistemas de aterramento de subestações — requisitos), expressamente indicada no critério, e o projeto de aterramento/malha de terra aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem as ligações equipotenciais, as seções dos condutores e os pontos de conexão. O critério integra o plano de inspeção da obra e constitui requisito verificável de aceitação, comprovado por medição de continuidade e de resistência de aterramento.',
  texto_risco_consequencia = 'Cercamento metálico não equipotencializado ou não aterrado no entorno de subestação pode assumir potencial elevado em falta à terra, submetendo quem toque a cerca a tensões de toque e de passo perigosas, com risco de choque elétrico e de acidente fatal; conexões ausentes ou corroídas invalidam a proteção presumida. A permanência da condição mantém ativo o risco elétrico grave até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir, contra o projeto de aterramento aprovado e a NBR 15751, todas as ligações equipotenciais da cerca — conexões de mourões e telas, cabos, conectores e amarrações à malha de terra; (ii) executar ou refazer as conexões faltantes ou deficientes e comprovar o desempenho por medição de continuidade e de resistência de aterramento, dentro dos limites de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar o laudo/medição de aterramento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-08' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica no perímetro de subestação ou de áreas energizadas, onde a ausência de sinalização de perigo elétrico aumenta diretamente o risco de aproximação indevida e de choque',
  texto_fundamentacao_normativa = 'A sinalização de advertência de "perigo elétrico" e de "área restrita" ao longo do perímetro informa e adverte trabalhadores e terceiros quanto ao risco e à restrição de acesso, atuando como medida de proteção coletiva. Aplica-se a NR-10, que determina a adoção de sinalização de segurança nas instalações e serviços em eletricidade, complementada pelo projeto/plano de sinalização aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define modelos, dizeres, espaçamento e locação das placas. O critério "Perigo elétrico e área restrita no perímetro" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência, o espaçamento excessivo ou a ilegibilidade das placas de advertência deixa pessoas sem o aviso de perigo elétrico e de restrição de acesso, aumentando a probabilidade de aproximação indevida ao perímetro energizado e de acidente por choque, além de caracterizar não atendimento a requisito de sinalização de segurança. A permanência da condição mantém o perímetro sem advertência adequada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar os pontos do perímetro sem sinalização e conferir dizeres, padrão, legibilidade e espaçamento das placas contra o projeto/plano de sinalização e a NR-10; (ii) instalar ou repor as placas de "perigo elétrico" e "área restrita" faltantes ou danificadas, garantindo visibilidade e locação ao longo de todo o perímetro; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'CV-08' and item_numero = 5;

